  log_level = debug
  reload_on_change = true
'';

# Development environment with redis
services.redis.enable = true;
services.redis.package = pkgs.redis;

environment.systemPackages = with pkgs; [
  git vim curl wget
  nodejs python3 rustc
];

# Development settings
services.redis.extraConfig = ''
  log_level = debug
  reload_on_change = true
'';

services.postgresql = {
  enable = true;
  package = pkgs.postgresql_15;
  enableTCPIP = true;
  authentication = pkgs.lib.mkOverride 10 ''
    local all all trust
    host all all 0.0.0.0/0 md5
  '';
};

# Development environment with networking
services.networking.enable = true;
services.networking.package = pkgs.networking;

environment.systemPackages = with pkgs; [
  git vim curl wget
  nodejs python3 rustc
];

# Development settings
services.networking.extraConfig = ''
  log_level = debug
  reload_on_change = true
'';

services.nginx = {
  enable = true;
  recommendedTlsSettings = true;

  virtualHosts."example.com" = {
    enableACME = true; forceSSL = true;
    locations."/" = {
      proxyPass = "http://localhost:3000";
    };
  };
};

nix.gc = {
  automatic = true;
  dates = "weekly";
  options = "--delete-older-than 7d";
};
nix.optimise.automatic = true;

